const BASE_SCORE = 2;
const FREE_TYPES = 3;
const SCORE_PER_EXTRA_TYPE = 2;

const countMonsterTypes = (cards: Card[]): number =>
  new Set(cards.map((card) => card.monster)).size;

const scoreSphinx = (otherCards: Card[]): number => {
  const extraTypes = Math.max(countMonsterTypes(otherCards) - FREE_TYPES, 0);
  return BASE_SCORE + SCORE_PER_EXTRA_TYPE * extraTypes;
};

export const scoreArmy = (army: Card[]): number => {
  const sphinxCount = army.filter(isSphinx).length;
  const otherCards = army.filter((card) => !isSphinx(card));
  return sphinxCount * scoreSphinx(otherCards);
};

