const BASE_SCORE = 2;
const FREE_TYPES = 3;
const SCORE_PER_EXTRA_TYPE = 2;

const countMonsterTypes = (cards: Card[]): number =>
  new Set(cards.map((card) => card.monster)).size;

const scoreSphinx = (otherCards: Card[]): number => {
  const typeCount = countMonsterTypes(otherCards);
  if (typeCount <= FREE_TYPES) return BASE_SCORE;
  return 1 + SCORE_PER_EXTRA_TYPE * (typeCount - FREE_TYPES);
};

